const SB_HEADERS = { apikey: SUPABASE_ANON_KEY, Authorization: `Bearer ${SUPABASE_ANON_KEY}` };

async function sbGet(key) {
  const res = await fetch(`${SUPABASE_URL}/rest/v1/app_data?key=eq.${encodeURIComponent(key)}&select=value`, { headers: SB_HEADERS });
  if (!res.ok) throw new Error("Supabase GET failed: " + res.status);
  const rows = await res.json();
  return rows && rows[0] ? rows[0].value : null;
}
async function sbSet(key, value) {
  const res = await fetch(`${SUPABASE_URL}/rest/v1/app_data?on_conflict=key`, {
    method: "POST",
    headers: { ...SB_HEADERS, "Content-Type": "application/json", "Prefer": "resolution=merge-duplicates,return=minimal" },
    body: JSON.stringify([{ key, value, updated_at: new Date().toISOString() }]),
  });
  if (!res.ok) throw new Error("Supabase SET failed: " + res.status);
}

