function getShopHours(dayIdx) { if (dayIdx === 5) return { open: 15 * 60, close: 22 * 60 }; return { open: 9 * 60, close: 22 * 60 }; }
function simpleHash(str) { let hash = 0; for (let i = 0; i < str.length; i++) { hash = (hash << 5) - hash + str.charCodeAt(i); hash |= 0; } return "h" + Math.abs(hash).toString(36) + btoa(unescape(encodeURIComponent(str))).slice(0, 8); }
BARBERS.forEach(b => { if (b.tempPassword) b.passwordHash = simpleHash(b.tempPassword); });
function uid() { return Date.now().toString(36) + Math.random().toString(36).slice(2, 8); }
function fmtDate(d) { const y = d.getFullYear(), m = String(d.getMonth() + 1).padStart(2, "0"), day = String(d.getDate()).padStart(2, "0"); return `${y}-${m}-${day}`; }
function minutesToLabel(mins) { const h = Math.floor(mins / 60), m = mins % 60; return `${String(h).padStart(2, "0")}:${String(m).padStart(2, "0")}`; }

