const LangContext = createContext(null);
function useLang() { return useContext(LangContext); }

/* ============================================================
   مكوّنات أساسية
============================================================ */
function Avatar({ initials, photo, size = 48 }) {
  if (photo) return <img src={photo} alt={initials} className="rounded-full object-cover shrink-0" style={{ width: size, height: size, border: "2px solid #C9A227" }} />;
  return <div className="flex items-center justify-center rounded-full font-bold shrink-0" style={{ width: size, height: size, background: "linear-gradient(135deg,#C9A227,#8a6d16)", color: "#0B0B0C", fontFamily: "'Playfair Display', serif", fontSize: size * 0.36 }}>{initials}</div>;
}
function getBarberPhoto(barberId, barberPhotos) {
  if (barberPhotos && barberPhotos[barberId]) return barberPhotos[barberId];
  const b = BARBERS.find(x => x.id === barberId);
  return b ? b.photo : null;
}
function fileToDataUrl(file, maxSize = 500, quality = 0.75) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => {
      const img = new Image();
      img.onload = () => {
        try {
          let { width, height } = img;
          if (width > maxSize || height > maxSize) {
            if (width > height) { height = Math.round(height * (maxSize / width)); width = maxSize; }
            else { width = Math.round(width * (maxSize / height)); height = maxSize; }
          }
          const canvas = document.createElement("canvas");
          canvas.width = width; canvas.height = height;
          const ctx = canvas.getContext("2d");
          ctx.drawImage(img, 0, 0, width, height);
          resolve(canvas.toDataURL("image/jpeg", quality));
        } catch (err) { reject(err); }
      };
      img.onerror = reject;
      img.src = reader.result;
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
}
function GoldDivider() { return <div className="h-[2px] w-14 mx-auto my-3" style={{ background: "linear-gradient(90deg,transparent,#C9A227,transparent)" }} />; }
function Card({ children, className = "", glow = false }) {
  return <div className={`rounded-2xl border p-4 ${className}`} style={{ background: "linear-gradient(180deg,#141414,#0f0f0f)", borderColor: glow ? "#C9A227" : "#262220", boxShadow: glow ? "0 0 0 1px rgba(201,162,39,0.25), 0 8px 24px rgba(201,162,39,0.08)" : "none" }}>{children}</div>;
}
function PrimaryButton({ children, onClick, disabled, className = "", type = "button" }) {
  return <button type={type} onClick={onClick} disabled={disabled} className={`w-full rounded-xl py-3.5 font-bold text-[15px] transition active:scale-[0.98] disabled:opacity-40 disabled:active:scale-100 ${className}`} style={{ background: disabled ? "#3a3226" : "linear-gradient(135deg,#E8C468,#C9A227)", color: "#0B0B0C" }}>{children}</button>;
}
function GhostButton({ children, onClick, className = "" }) {
  return <button onClick={onClick} className={`rounded-xl py-3 px-4 font-semibold text-sm border transition active:scale-[0.98] ${className}`} style={{ borderColor: "#3a352f", color: "#E8C468", background: "transparent" }}>{children}</button>;
}
function Field({ label, icon, children }) { return <div><label className="flex items-center gap-1.5 text-xs font-semibold mb-1.5" style={{ color: "#9B9691" }}>{icon}{label}</label>{children}</div>; }
function Section({ title, children }) { return <div><h3 className="text-sm font-extrabold mb-2" style={{ color: "#E8C468" }}>{title}</h3>{children}</div>; }
function Row({ label, value, bold }) { return <div className="flex items-center justify-between"><span className={`text-sm ${bold ? "font-extrabold" : ""}`} style={{ color: bold ? "#E8C468" : "#9B9691" }}>{label}</span><span className={`text-sm ${bold ? "font-extrabold text-base" : "font-semibold"}`} style={{ color: bold ? "#E8C468" : "#F5F0E6" }}>{value}</span></div>; }
function EmptyMsg({ text }) { const t = useLang().t; return <Card><p className="text-sm text-center" style={{ color: "#9B9691" }}>{text || t.emptyHere}</p></Card>; }

function LangSwitcher({ compact }) {
  const { lang, setLang } = useLang();
  const opts = [{ k: "ar", l: "AR" }, { k: "fr", l: "FR" }, { k: "en", l: "EN" }];
  return (
    <div className="flex gap-1">
      {opts.map(o => (
        <button key={o.k} onClick={() => setLang(o.k)}
          className={`rounded-lg font-bold ${compact ? "text-[10px] px-1.5 py-1" : "text-xs px-2.5 py-1.5"}`}
          style={{ background: lang === o.k ? "#C9A227" : "transparent", color: lang === o.k ? "#0B0B0C" : "#9B9691", border: "1px solid #3a352f" }}>
          {o.l}
        </button>
      ))}
    </div>
  );
}

/* ============================================================
   التطبيق الرئيسي
============================================================ */
export default function App() {
  const [lang, setLang] = useState("ar");
  const [now, setNow] = useState(new Date());
  const [loaded, setLoaded] = useState(false);
  const [users, setUsers] = useState([]);
  const [bookings, setBookings] = useState([]);
  const [reviews, setReviews] = useState([]);
  const [notifications, setNotifications] = useState([]);
  const [shopStatus, setShopStatus] = useState({ override: null });
  const [barberPhotos, setBarberPhotos] = useState({});

  const [role, setRole] = useState(null);
  const [currentUsername, setCurrentUsername] = useState(null);
  const [tab, setTab] = useState("home");
  const [toast, setToast] = useState(null);

  const t = T[lang];
  const currentUser = useMemo(() => users.find(u => u.username === currentUsername) || null, [users, currentUsername]);
  const currentBarber = useMemo(() => BARBERS.find(b => b.id === currentUsername) || null, [currentUsername]);

  const loadAll = useCallback(async (isFirstLoad) => {
    try {
      const [u, b, r, n, s, bp] = await Promise.allSettled([
        sbGet("app:users"), sbGet("app:bookings"), sbGet("app:reviews"),
        sbGet("app:notifications"), sbGet("app:shopstatus"), sbGet("app:barberphotos"),
      ]);
      setUsers(u.status === "fulfilled" && u.value ? u.value : []);
      setBookings(b.status === "fulfilled" && b.value ? b.value : []);
      setReviews(r.status === "fulfilled" && r.value ? r.value : []);
      setNotifications(n.status === "fulfilled" && n.value ? n.value : []);
      setShopStatus(s.status === "fulfilled" && s.value ? s.value : { override: null });
      setBarberPhotos(bp.status === "fulfilled" && bp.value ? bp.value : {});
    } catch (e) { console.error(e); }
    if (isFirstLoad) setLoaded(true);
  }, []);

  useEffect(() => { loadAll(true); }, [loadAll]);

  // تحديث تلقائي دوري (مزامنة شبه فورية بين كل الأجهزة) + تحريك الساعة
  useEffect(() => {
    const tm = setInterval(() => { setNow(new Date()); loadAll(false); }, 15000);
    return () => clearInterval(tm);
  }, [loadAll]);

  // تحديث فوري عند رجوع المستخدم للصفحة (تبديل تبويب/تطبيق)
  useEffect(() => {
    function onVisible() { if (document.visibilityState === "visible") loadAll(false); }
    document.addEventListener("visibilitychange", onVisible);
    return () => document.removeEventListener("visibilitychange", onVisible);
  }, [loadAll]);

  const persistUsers = useCallback(async (next) => { setUsers(next); try { await sbSet("app:users", next); } catch (e) { console.error(e); } }, []);
  const persistBookings = useCallback(async (next) => { setBookings(next); try { await sbSet("app:bookings", next); } catch (e) { console.error(e); } }, []);
  const persistReviews = useCallback(async (next) => { setReviews(next); try { await sbSet("app:reviews", next); } catch (e) { console.error(e); } }, []);
  const persistNotifications = useCallback(async (next) => { setNotifications(next); try { await sbSet("app:notifications", next); } catch (e) { console.error(e); } }, []);
  const persistShopStatus = useCallback(async (next) => { setShopStatus(next); try { await sbSet("app:shopstatus", next); } catch (e) { console.error(e); } }, []);
  const persistBarberPhotos = useCallback(async (next) => { setBarberPhotos(next); try { await sbSet("app:barberphotos", next); } catch (e) { console.error(e); } }, []);

  function pushNotification(list, entry) { return [{ id: uid(), createdAt: Date.now(), read: false, ...entry }, ...list]; }
  function showToast(msg, type = "ok") { setToast({ msg, type }); setTimeout(() => setToast(null), 2600); }
  function logout() { setRole(null); setCurrentUsername(null); setTab("home"); }

  function isShopOpenNow(d = new Date()) {
    if (shopStatus.override === true) return true;
    if (shopStatus.override === false) return false;
    const dayIdx = d.getDay(); const { open, close } = getShopHours(dayIdx); const mins = d.getHours() * 60 + d.getMinutes();
    return mins >= open && mins < close;
  }

  if (!loaded) {
    return (
      <div className="min-h-screen flex items-center justify-center" style={{ background: "#0B0B0C" }}>
        <div className="text-center"><Scissors className="animate-pulse mx-auto mb-3" color="#C9A227" size={36} /><p style={{ color: "#C9A227" }} className="font-semibold">...</p></div>
      </div>
    );
  }

  return (
    <LangContext.Provider value={{ lang, setLang, t }}>
      <div dir={t.dir} className="min-h-screen" style={{ background: "#0B0B0C", color: "#F5F0E6", fontFamily: "'Manrope',sans-serif" }}>
        <style>{`
          @import url('https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700;800&family=Manrope:wght@400;500;600;700;800&display=swap');
          * { box-sizing: border-box; }
          input, textarea { font-family: 'Manrope', sans-serif; }
          ::selection { background: #C9A227; color: #0B0B0C; }
          .auth-input { width:100%; background:#0B0B0C; border:1px solid #3a352f; border-radius:10px; padding:11px 12px; color:#F5F0E6; font-size:14px; outline:none; }
          .auth-input:focus { border-color:#C9A227; }
        `}</style>

        {toast && (
          <div className="fixed top-4 left-1/2 -translate-x-1/2 z-50 px-4 py-2.5 rounded-xl text-sm font-bold shadow-lg" style={{ background: toast.type === "err" ? "#3a1414" : "#1a2a1a", color: toast.type === "err" ? "#ff8a8a" : "#9be89b", border: `1px solid ${toast.type === "err" ? "#7a2b2b" : "#2f6b2f"}` }}>{toast.msg}</div>
        )}

        {!role ? (
          <AuthScreen users={users} persistUsers={persistUsers} onLoginSuccess={(u, r) => { setCurrentUsername(u); setRole(r); setTab("home"); }} showToast={showToast} />
        ) : role === "customer" ? (
          <CustomerApp now={now} isShopOpenNow={isShopOpenNow} currentUser={currentUser} users={users} persistUsers={persistUsers}
            bookings={bookings} persistBookings={persistBookings} reviews={reviews} persistReviews={persistReviews}
            notifications={notifications} persistNotifications={persistNotifications} pushNotification={pushNotification}
            barberPhotos={barberPhotos}
            tab={tab} setTab={setTab} onLogout={logout} showToast={showToast} />
        ) : role === "barber" ? (
          <BarberApp now={now} isShopOpenNow={isShopOpenNow} barber={currentBarber} bookings={bookings} persistBookings={persistBookings}
            users={users} persistUsers={persistUsers} notifications={notifications} persistNotifications={persistNotifications} pushNotification={pushNotification}
            barberPhotos={barberPhotos} persistBarberPhotos={persistBarberPhotos}
            tab={tab} setTab={setTab} onLogout={logout} showToast={showToast} />
        ) : (
          <OwnerApp now={now} isShopOpenNow={isShopOpenNow} shopStatus={shopStatus} persistShopStatus={persistShopStatus}
            bookings={bookings} persistBookings={persistBookings} users={users} persistUsers={persistUsers} reviews={reviews}
            notifications={notifications} persistNotifications={persistNotifications} pushNotification={pushNotification}
            barberPhotos={barberPhotos} persistBarberPhotos={persistBarberPhotos}
            tab={tab} setTab={setTab} onLogout={logout} showToast={showToast} />
        )}
      </div>
    </LangContext.Provider>
  );
}

/* ============================================================
   شاشة الدخول / التسجيل
============================================================ */
function AuthScreen({ users, persistUsers, onLoginSuccess, showToast }) {
  const { t } = useLang();
  const [authMode, setAuthMode] = useState("login");
  const [authTarget, setAuthTarget] = useState("customer");
  const [fullName, setFullName] = useState(""); const [username, setUsername] = useState(""); const [password, setPassword] = useState("");
  const [showPass, setShowPass] = useState(false); const [secAnswer, setSecAnswer] = useState("");
  const [forgotStep, setForgotStep] = useState(1); const [forgotUser, setForgotUser] = useState(null);
  const [answerInput, setAnswerInput] = useState(""); const [newPass, setNewPass] = useState("");

  function resetFields() { setFullName(""); setUsername(""); setPassword(""); setSecAnswer(""); setForgotStep(1); setForgotUser(null); setAnswerInput(""); setNewPass(""); }
  function handleOwnerLogin() { if (username === "yassine666*" && password === "yazz1X") onLoginSuccess("owner", "owner"); else showToast(t.errWrongCreds, "err"); }
  function handleBarberLogin() {
    const b = BARBERS.find(x => x.username === username.trim());
    if (!b) return showToast(t.errNoBarber, "err");
    if (b.passwordHash !== simpleHash(password)) return showToast(t.errWrongPass, "err");
    onLoginSuccess(b.id, "barber");
  }
  function handleCustomerLogin() {
    const u = users.find(x => x.username === username.trim());
    if (!u) return showToast(t.errNoAccount, "err");
    if (u.passwordHash !== simpleHash(password)) return showToast(t.errWrongPass, "err");
    onLoginSuccess(u.username, "customer");
  }
  function handleSignup() {
    if (!fullName.trim() || !username.trim() || !password.trim() || !secAnswer.trim()) return showToast(t.errFillAll, "err");
    if (users.some(u => u.username === username.trim())) return showToast(t.errUsernameTaken, "err");
    const newUser = { username: username.trim(), fullName: fullName.trim(), passwordHash: simpleHash(password), securityAnswerHash: simpleHash(secAnswer.trim().toLowerCase()), loyaltyCount: 0, missedCount: 0, createdAt: Date.now() };
    persistUsers([...users, newUser]); showToast(t.okSignup); onLoginSuccess(newUser.username, "customer");
  }
  function handleForgotStart() { const u = users.find(x => x.username === username.trim()); if (!u) return showToast(t.errNoAccount, "err"); setForgotUser(u); setForgotStep(2); }
  function handleForgotVerify() { if (simpleHash(answerInput.trim().toLowerCase()) !== forgotUser.securityAnswerHash) return showToast(t.errWrongAnswer, "err"); setForgotStep(3); }
  function handleForgotReset() { if (!newPass.trim() || newPass.length < 4) return showToast(t.errShortPass, "err"); persistUsers(users.map(u => u.username === forgotUser.username ? { ...u, passwordHash: simpleHash(newPass) } : u)); showToast(t.okPassReset); setAuthMode("login"); resetFields(); }

  const targets = [{ key: "customer", label: t.roleCustomer }, { key: "barber", label: t.roleBarber }, { key: "owner", label: t.roleOwner }];

  return (
    <div className="min-h-screen flex flex-col items-center justify-center px-5 py-10">
      <div className="w-full max-w-sm">
        <div className="flex justify-center mb-4"><LangSwitcher /></div>
        <div className="text-center mb-6">
          <img src={IMAGES.logo} alt={SHOP_NAME} className="mx-auto mb-3 w-24 h-24 rounded-full object-cover" style={{ border: "2px solid #C9A227", boxShadow: "0 0 24px rgba(201,162,39,0.35)" }} />
          <p className="text-xs" style={{ color: "#9B9691" }}>{t.tagline}</p>
          <GoldDivider />
        </div>

        <div className="grid grid-cols-3 gap-2 mb-4">
          {targets.map(tg => (
            <button key={tg.key} onClick={() => { setAuthTarget(tg.key); setAuthMode("login"); resetFields(); }} className="rounded-xl py-2.5 font-bold text-xs border transition"
              style={{ background: authTarget === tg.key ? "linear-gradient(135deg,#E8C468,#C9A227)" : "transparent", color: authTarget === tg.key ? "#0B0B0C" : "#E8C468", borderColor: "#3a352f" }}>{tg.label}</button>
          ))}
        </div>

        {authTarget === "owner" && (
          <Card className="space-y-3">
            <Field label={t.ownerUsernameLabel} icon={<User size={16} color="#9B9691" />}><input className="auth-input" value={username} onChange={e => setUsername(e.target.value)} /></Field>
            <Field label={t.passwordLabel} icon={<Lock size={16} color="#9B9691" />}><div className="flex items-center gap-2"><input type={showPass ? "text" : "password"} className="auth-input flex-1" value={password} onChange={e => setPassword(e.target.value)} /><button onClick={() => setShowPass(s => !s)}>{showPass ? <EyeOff size={18} color="#9B9691" /> : <Eye size={18} color="#9B9691" />}</button></div></Field>
            <PrimaryButton onClick={handleOwnerLogin}>{t.loginBtn}</PrimaryButton>
          </Card>
        )}

        {authTarget === "barber" && (
          <Card className="space-y-3">
            <Field label={t.usernameLabel} icon={<User size={16} color="#9B9691" />}><input className="auth-input" value={username} onChange={e => setUsername(e.target.value)} /></Field>
            <Field label={t.passwordLabel} icon={<Lock size={16} color="#9B9691" />}><div className="flex items-center gap-2"><input type={showPass ? "text" : "password"} className="auth-input flex-1" value={password} onChange={e => setPassword(e.target.value)} /><button onClick={() => setShowPass(s => !s)}>{showPass ? <EyeOff size={18} color="#9B9691" /> : <Eye size={18} color="#9B9691" />}</button></div></Field>
            <PrimaryButton onClick={handleBarberLogin}>{t.loginBtn}</PrimaryButton>
          </Card>
        )}

        {authTarget === "customer" && authMode === "login" && (
          <Card className="space-y-3">
            <Field label={t.usernameLabel} icon={<User size={16} color="#9B9691" />}><input className="auth-input" value={username} onChange={e => setUsername(e.target.value)} /></Field>
            <Field label={t.passwordLabel} icon={<Lock size={16} color="#9B9691" />}><div className="flex items-center gap-2"><input type={showPass ? "text" : "password"} className="auth-input flex-1" value={password} onChange={e => setPassword(e.target.value)} /><button onClick={() => setShowPass(s => !s)}>{showPass ? <EyeOff size={18} color="#9B9691" /> : <Eye size={18} color="#9B9691" />}</button></div></Field>
            <PrimaryButton onClick={handleCustomerLogin}>{t.loginBtn}</PrimaryButton>
            <div className="flex justify-between text-xs pt-1">
              <button onClick={() => { setAuthMode("signup"); resetFields(); }} style={{ color: "#E8C468" }} className="font-semibold">{t.newCustomerQ}</button>
              <button onClick={() => { setAuthMode("forgot"); resetFields(); }} style={{ color: "#9B9691" }} className="font-semibold">{t.forgotPassword}</button>
            </div>
          </Card>
        )}

        {authTarget === "customer" && authMode === "signup" && (
          <Card className="space-y-3">
            <Field label={t.fullNameLabel} icon={<User size={16} color="#9B9691" />}><input className="auth-input" value={fullName} onChange={e => setFullName(e.target.value)} /></Field>
            <Field label={t.chooseUsername} icon={<User size={16} color="#9B9691" />}><input className="auth-input" value={username} onChange={e => setUsername(e.target.value)} /></Field>
            <Field label={t.choosePassword} icon={<Lock size={16} color="#9B9691" />}><input type={showPass ? "text" : "password"} className="auth-input" value={password} onChange={e => setPassword(e.target.value)} /></Field>
            <Field label={t.securityQFixed} icon={<ShieldQuestion size={16} color="#9B9691" />}><input className="auth-input" value={secAnswer} onChange={e => setSecAnswer(e.target.value)} placeholder={t.securityAnswerLabel} /></Field>
            <PrimaryButton onClick={handleSignup}>{t.signupBtn}</PrimaryButton>
            <button onClick={() => { setAuthMode("login"); resetFields(); }} className="text-xs font-semibold block mx-auto pt-1" style={{ color: "#9B9691" }}>{t.haveAccountQ}</button>
          </Card>
        )}

        {authTarget === "customer" && authMode === "forgot" && (
          <Card className="space-y-3">
            {forgotStep === 1 && (<><Field label={t.usernameLabel} icon={<User size={16} color="#9B9691" />}><input className="auth-input" value={username} onChange={e => setUsername(e.target.value)} /></Field><PrimaryButton onClick={handleForgotStart}>{t.continueBtn}</PrimaryButton></>)}
            {forgotStep === 2 && forgotUser && (<><p className="text-sm font-semibold" style={{ color: "#E8C468" }}>{t.securityQFixed}</p><Field label={t.securityAnswerLabel} icon={<KeyRound size={16} color="#9B9691" />}><input className="auth-input" value={answerInput} onChange={e => setAnswerInput(e.target.value)} /></Field><PrimaryButton onClick={handleForgotVerify}>{t.verifyBtn}</PrimaryButton></>)}
            {forgotStep === 3 && (<><Field label={t.newPasswordLabel} icon={<Lock size={16} color="#9B9691" />}><input type="password" className="auth-input" value={newPass} onChange={e => setNewPass(e.target.value)} /></Field><PrimaryButton onClick={handleForgotReset}>{t.savePasswordBtn}</PrimaryButton></>)}
            <button onClick={() => { setAuthMode("login"); resetFields(); }} className="text-xs font-semibold block mx-auto pt-1" style={{ color: "#9B9691" }}>{t.backToLogin}</button>
          </Card>
        )}

        <div className="text-center mt-8">
          <p className="font-extrabold text-sm tracking-[0.3em]" style={{ fontFamily: "'Playfair Display',serif", color: "#fff", textShadow: "0 0 12px rgba(255,255,255,0.55), 0 0 2px #fff" }}>YAZZY BARBER</p>
        </div>
      </div>
    </div>
  );
}

/* ============================================================
   عناصر مشتركة
============================================================ */
function NotifBell({ list, onOpen }) {
  const unread = list.filter(n => !n.read).length;
  return (<button onClick={onOpen} className="relative"><Bell size={18} color="#9B9691" />{unread > 0 && <span className="absolute -top-1.5 -left-1.5 min-w-[16px] h-4 px-1 rounded-full text-[9px] font-bold flex items-center justify-center" style={{ background: "#C9A227", color: "#0B0B0C" }}>{unread}</span>}</button>);
}
function NotifModal({ list, onClose }) {
  const { t } = useLang();
  return (
    <div className="fixed inset-0 z-50 flex items-start justify-center p-4 pt-20" style={{ background: "rgba(0,0,0,0.7)" }} onClick={onClose}>
      <div className="w-full max-w-sm rounded-2xl p-4 max-h-[70vh] overflow-y-auto" style={{ background: "#141414", border: "1px solid #C9A227" }} onClick={e => e.stopPropagation()}>
        <div className="flex items-center justify-between mb-3"><h3 className="font-extrabold text-sm" style={{ color: "#E8C468" }}>{t.notifications}</h3><button onClick={onClose}><X size={18} color="#9B9691" /></button></div>
        {list.length === 0 ? <p className="text-sm text-center py-6" style={{ color: "#9B9691" }}>{t.noNotifications}</p> : (
          <div className="space-y-2">{list.map(n => (<div key={n.id} className="rounded-xl p-3" style={{ background: n.read ? "#0B0B0C" : "#1a1712", border: "1px solid #262220" }}><p className="text-xs font-semibold">{n.message}</p><p className="text-[10px] mt-1" style={{ color: "#6b655c" }}>{new Date(n.createdAt).toLocaleString()}</p></div>))}</div>
        )}
      </div>
    </div>
  );
}
function TopBar({ subtitle, onLogout, notifList, onOpenNotif, isShopOpenNow }) {
  const { t } = useLang();
  const open = isShopOpenNow();
  return (
    <div className="sticky top-0 z-30 px-4 pt-4 pb-3 border-b" style={{ background: "rgba(11,11,12,0.92)", backdropFilter: "blur(6px)", borderColor: "#201d19" }}>
      <div className="flex items-start justify-between gap-2">
        <div className="flex items-center gap-2 min-w-0 shrink">
          <img src={IMAGES.logo} alt="" className="w-9 h-9 rounded-full object-cover shrink-0" style={{ border: "1px solid #C9A227" }} />
          <div className="min-w-0">
            <p className="font-extrabold text-[14px] truncate" style={{ fontFamily: "'Playfair Display',serif", color: "#E8C468" }}>{SHOP_NAME}</p>
            <p className="text-[10px] truncate" style={{ color: "#9B9691" }}>{subtitle}</p>
          </div>
        </div>
        <div className="flex flex-col items-end gap-1.5 shrink-0">
          <div className="flex items-center gap-1.5">
            <LangSwitcher compact />
            <button onClick={onLogout} title={t.logout} className="shrink-0"><LogOut size={17} color="#9B9691" /></button>
          </div>
          <div className="flex items-center gap-1.5">
            <span className="text-[9px] font-bold px-1.5 py-0.5 rounded-full whitespace-nowrap" style={{ background: open ? "#132a17" : "#2a1414", color: open ? "#7be08a" : "#ff9b9b" }}>{open ? t.openNow : t.closedNow}</span>
            {notifList && <NotifBell list={notifList} onOpen={onOpenNotif} />}
          </div>
        </div>
      </div>
    </div>
  );
}
function BottomNav({ items, tab, setTab }) {
  return (
    <div className="fixed bottom-0 left-0 right-0 z-40 border-t" style={{ background: "#0f0f0f", borderColor: "#262220" }}>
      <div className="max-w-md mx-auto grid" style={{ gridTemplateColumns: `repeat(${items.length},1fr)` }}>
        {items.map(it => { const active = tab === it.key; return (<button key={it.key} onClick={() => setTab(it.key)} className="flex flex-col items-center gap-1 py-2.5"><it.icon size={20} color={active ? "#E8C468" : "#6b655c"} /><span className="text-[10px] font-bold" style={{ color: active ? "#E8C468" : "#6b655c" }}>{it.label}</span></button>); })}
      </div>
    </div>
  );
}
function ReminderBanner({ booking }) {
  const { t, lang } = useLang();
  if (!booking) return null;
  const barber = BARBERS.find(b => b.id === booking.barberId);
  return (
    <div className="px-4 pt-3"><div className="max-w-md mx-auto rounded-xl p-3 flex items-center gap-2" style={{ background: "linear-gradient(90deg,#2a2010,#1a1712)", border: "1px solid #C9A227" }}>
      <Zap size={18} color="#E8C468" className="shrink-0" /><p className="text-xs font-bold" style={{ color: "#E8C468" }}>{t.reminderBanner(barber?.name, booking.time)}</p>
    </div></div>
  );
}

function statusLabel(t, status) {
  return { pending: { label: t.statusPending, color: "#e8b84b" }, awaiting_arrival: { label: t.statusAwaiting, color: "#4ba3e8" }, completed: { label: t.statusCompleted, color: "#7be08a" }, no_show: { label: t.statusNoShow, color: "#ff8a8a" } }[status];
}

/* ============================================================
   تطبيق الزبون
============================================================ */
function CustomerApp({ now, isShopOpenNow, currentUser, users, persistUsers, bookings, persistBookings, reviews, persistReviews, notifications, persistNotifications, pushNotification, barberPhotos, tab, setTab, onLogout, showToast }) {
  const { t, lang } = useLang();
  const [showNotif, setShowNotif] = useState(false);
  const [bookSubview, setBookSubview] = useState("normal");
  const myBookings = bookings.filter(b => b.customerUsername === currentUser.username);
  const upcoming = myBookings.filter(b => b.status === "pending" || b.status === "awaiting_arrival");
  const past = myBookings.filter(b => b.status === "completed" || b.status === "no_show");
  const needsRating = myBookings.find(b => b.status === "completed" && b.rated === false);
  const myNotifs = notifications.filter(n => n.forRole === "customer" && n.forUsername === currentUser.username);
  const hasActiveBooking = upcoming.length > 0;

  const soonBooking = useMemo(() => {
    return upcoming.find(b => {
      if (b.status !== "awaiting_arrival") return false;
      const bTime = new Date(`${b.date}T${b.time}:00`);
      const diff = bTime.getTime() - now.getTime();
      return diff > 0 && diff <= 60 * 60000;
    });
  }, [upcoming, now]);

  const navItems = [
    { key: "home", label: t.navHome, icon: Home }, { key: "book", label: t.navBook, icon: Calendar },
    { key: "services", label: t.navServices, icon: Scissors }, { key: "reviews", label: t.navReviews, icon: Star },
    { key: "account", label: t.navAccount, icon: User },
  ];

  function cancelBooking(id) { persistBookings(bookings.filter(b => b.id !== id)); showToast(t.okCancelledByBarber); }
  function submitRating(rating, comment) {
    persistReviews([{ id: uid(), customerName: currentUser.fullName, rating, comment, createdAt: Date.now() }, ...reviews]);
    persistBookings(bookings.map(b => b.id === needsRating.id ? { ...b, rated: true } : b));
    showToast(t.okRatingSent);
  }
  function openNotif() { setShowNotif(true); persistNotifications(notifications.map(n => (n.forRole === "customer" && n.forUsername === currentUser.username) ? { ...n, read: true } : n)); }

  return (
    <div className="pb-20">
      <TopBar subtitle={t.bookNowTag} onLogout={onLogout} notifList={myNotifs} onOpenNotif={openNotif} isShopOpenNow={isShopOpenNow} />
      <ReminderBanner booking={soonBooking} />
      {showNotif && <NotifModal list={myNotifs} onClose={() => setShowNotif(false)} />}
      {needsRating && <RatingModal onSubmit={submitRating} />}
      <div className="px-4 pt-4 max-w-md mx-auto">
        {tab === "home" && <HomeSection reviews={reviews} bookings={bookings} now={now} barberPhotos={barberPhotos} />}
        {tab === "book" && bookSubview === "normal" && (
          <div className="space-y-3">
            <button onClick={() => setBookSubview("groom")} className="w-full rounded-2xl py-3.5 font-extrabold text-sm flex items-center justify-center gap-2" style={{ background: "linear-gradient(135deg,#3a2f10,#1a1712)", border: "1px solid #C9A227", color: "#E8C468" }}>
              <Crown size={17} />{t.groomTabBtn}
            </button>
            <BookingWizard now={now} currentUser={currentUser} bookings={bookings} persistBookings={persistBookings} notifications={notifications} persistNotifications={persistNotifications} pushNotification={pushNotification} showToast={showToast} onDone={() => setTab("account")} hasActiveBooking={hasActiveBooking} barberPhotos={barberPhotos} />
          </div>
        )}
        {tab === "book" && bookSubview === "groom" && (
          <GroomSection now={now} currentUser={currentUser} bookings={bookings} persistBookings={persistBookings} notifications={notifications} persistNotifications={persistNotifications} pushNotification={pushNotification} showToast={showToast} barberPhotos={barberPhotos} hasActiveBooking={hasActiveBooking} onBack={() => setBookSubview("normal")} onDone={() => { setBookSubview("normal"); setTab("account"); }} />
        )}
        {tab === "services" && <ServicesSection />}
        {tab === "reviews" && <ReviewsSection reviews={reviews} />}
        {tab === "account" && <AccountSection currentUser={currentUser} upcoming={upcoming} past={past} bookings={bookings} onCancel={cancelBooking} users={users} persistUsers={persistUsers} showToast={showToast} />}
      </div>
      <BottomNav items={navItems} tab={tab} setTab={setTab} />
    </div>
  );
}

function HomeSection({ reviews, bookings, now, barberPhotos }) {
  const { t, lang } = useLang();
  const avgRating = reviews.length ? (reviews.reduce((s, r) => s + r.rating, 0) / reviews.length).toFixed(1) : "0.0";
  const todayStr = fmtDate(now);
  const waitingNow = bookings.filter(b => b.status === "awaiting_arrival" && b.date === todayStr).length;

  return (
    <div className="space-y-4">
      <div className="rounded-2xl overflow-hidden relative" style={{ border: "1px solid #262220" }}>
        <div className="relative" style={{ minHeight: 260 }}>
          <img src={IMAGES.hero} alt="" className="absolute inset-0 w-full h-full object-cover" />
          <div className="absolute inset-0" style={{ background: "linear-gradient(180deg,rgba(11,11,12,0.55),rgba(11,11,12,0.92))" }} />
          <div className="relative p-6 text-center">
            <p className="text-[11px] tracking-widest font-bold mb-1" style={{ color: "#E8C468" }}>{t.heroTag}</p>
            <h2 className="text-2xl font-extrabold leading-tight whitespace-pre-line" style={{ fontFamily: "'Playfair Display',serif", color: "#fff", textShadow: "0 2px 10px rgba(0,0,0,0.7)" }}>{t.heroTitle}</h2>
            <GoldDivider />
            <p className="text-xs leading-relaxed whitespace-pre-line" style={{ color: "#e8e3da" }}>{t.heroHours}</p>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-3 gap-2">
        <Card className="text-center !p-3"><p className="text-lg font-extrabold" style={{ color: "#E8C468" }}>{avgRating} ★</p><p className="text-[10px] mt-1" style={{ color: "#9B9691" }}>{t.ratingLabel}</p></Card>
        <Card className="text-center !p-3"><p className="text-lg font-extrabold" style={{ color: "#E8C468" }}>{BOOKING_FEE} {t.currency}</p><p className="text-[10px] mt-1" style={{ color: "#9B9691" }}>{t.feeLabel}</p></Card>
        <Card className="text-center !p-3"><p className="text-lg font-extrabold" style={{ color: "#E8C468" }}>{waitingNow}</p><p className="text-[10px] mt-1" style={{ color: "#9B9691" }}>{t.waitingNowLabel}</p></Card>
      </div>

      <Section title={t.barbersTitle}>
        <div className="grid grid-cols-2 gap-2">
          {BARBERS.map(b => {
            const todayCount = bookings.filter(x => x.barberId === b.id && x.date === todayStr && x.status === "awaiting_arrival").length;
            const completedTotal = bookings.filter(x => x.barberId === b.id && x.status === "completed").length;
            return (
              <Card key={b.id} className="text-center !p-3">
                <Avatar initials={b.initials} photo={getBarberPhoto(b.id, barberPhotos)} size={52} />
                <p className="text-xs font-bold mt-2">{b.name}</p>
                <p className="text-[10px] mt-0.5" style={{ color: "#9B9691" }}>{t.todayLabel}: {todayCount}</p>
                <p className="text-[10px]" style={{ color: "#6b655c" }}>{t.totalLabel}: {completedTotal}</p>
              </Card>
            );
          })}
        </div>
      </Section>

      <Section title={t.shopPhotosTitle}><img src={IMAGES.shop} alt={SHOP_NAME} className="w-full rounded-2xl object-cover" style={{ maxHeight: 220, border: "1px solid #262220" }} /></Section>
      <Section title={t.locationTitle}><a href={MAPS_URL} target="_blank" rel="noreferrer"><Card className="flex items-center justify-between"><div className="flex items-center gap-2"><MapPin size={18} color="#C9A227" /><span className="text-sm font-semibold">{t.openMaps}</span></div><ArrowLeft size={16} color="#9B9691" style={lang !== "ar" ? { transform: "scaleX(-1)" } : {}} /></Card></a></Section>
      <Section title={t.contactTitle}>
        <Card className="space-y-3">
          <a href={`tel:${SHOP_PHONE}`} className="flex items-center gap-2"><Phone size={16} color="#C9A227" /><span className="text-sm font-semibold" dir="ltr">{SHOP_PHONE}</span></a>
          <div className="flex gap-2"><a href={INSTAGRAM_URL} target="_blank" rel="noreferrer" className="flex-1"><GhostButton className="w-full text-center"><span className="flex items-center justify-center gap-1.5"><Instagram size={15} />Instagram</span></GhostButton></a><a href={TIKTOK_URL} target="_blank" rel="noreferrer" className="flex-1"><GhostButton className="w-full text-center">TikTok</GhostButton></a></div>
        </Card>
      </Section>
    </div>
  );
}

function ServicesSection() {
  const { t, lang } = useLang();
  return (
    <div className="space-y-4">
      <div className="text-center py-2"><h2 className="text-xl font-extrabold" style={{ fontFamily: "'Playfair Display',serif", color: "#E8C468" }}>{t.servicesTitle}</h2><p className="text-xs mt-1" style={{ color: "#9B9691" }}>{t.servicesSubtitle}</p></div>
      <div className="space-y-2">
        {SERVICES.map(s => (<Card key={s.id} className="flex items-center justify-between"><div><p className="font-bold text-sm">{s.name[lang]}</p><p className="text-[11px]" style={{ color: "#6b655c" }}>{t.minutesApprox} {s.duration} {t.minutesUnit}</p></div><p className="font-extrabold" style={{ color: "#E8C468" }}>{s.price.toLocaleString()} {t.currency}</p></Card>))}
        <Card className="!border-[#C9A227]"><div className="flex items-center justify-between"><p className="font-bold text-sm">{t.feeCashNote}</p><p className="font-extrabold" style={{ color: "#E8C468" }}>{BOOKING_FEE} {t.currency}</p></div></Card>
      </div>
    </div>
  );
}

function ReviewsSection({ reviews }) {
  const { t } = useLang();
  const avg = reviews.length ? (reviews.reduce((s, r) => s + r.rating, 0) / reviews.length).toFixed(1) : "0.0";
  return (
    <div className="space-y-4">
      <div className="text-center py-4"><p className="text-4xl font-extrabold" style={{ color: "#E8C468" }}>{avg}</p><div className="flex justify-center gap-0.5 my-1">{Array.from({ length: 5 }).map((_, i) => <Star key={i} size={18} fill={i < Math.round(avg) ? "#C9A227" : "none"} color="#C9A227" />)}</div><p className="text-xs" style={{ color: "#9B9691" }}>{reviews.length}</p></div>
      {reviews.length === 0 ? <EmptyMsg text={t.noReviewsYet} /> : (
        <div className="space-y-2">{reviews.map(r => (<Card key={r.id}><div className="flex items-center justify-between mb-1"><p className="text-sm font-bold">{r.customerName}</p><div className="flex items-center gap-0.5">{Array.from({ length: 5 }).map((_, i) => <Star key={i} size={13} fill={i < r.rating ? "#C9A227" : "none"} color="#C9A227" />)}</div></div>{r.comment && <p className="text-xs" style={{ color: "#9B9691" }}>{r.comment}</p>}<p className="text-[10px] mt-1" style={{ color: "#544e46" }}>{new Date(r.createdAt).toLocaleDateString()}</p></Card>))}</div>
      )}
    </div>
  );
}

/* ---------------- معالج الحجز ---------------- */
function BookingWizard({ now, currentUser, bookings, persistBookings, notifications, persistNotifications, pushNotification, showToast, onDone, hasActiveBooking, barberPhotos }) {
  const { t, lang } = useLang();
  const [step, setStep] = useState(0);
  const [barberId, setBarberId] = useState(null);
  const [serviceIds, setServiceIds] = useState([]);
  const [phone, setPhone] = useState(""); const [wilaya, setWilaya] = useState(""); const [note, setNote] = useState("");
  const [date, setDate] = useState(null); const [time, setTime] = useState(null);

  const barber = BARBERS.find(b => b.id === barberId);
  const chosenServices = SERVICES.filter(s => serviceIds.includes(s.id));
  const totalPrice = chosenServices.reduce((s, x) => s + x.price, 0);
  const totalDuration = chosenServices.reduce((s, x) => s + x.duration, 0) || DEFAULT_DURATION;
  const grandTotal = totalPrice + BOOKING_FEE;
  const todayStr = fmtDate(now);
  const barberTodayQueue = barberId ? bookings.filter(b => b.barberId === barberId && b.date === todayStr && b.status === "awaiting_arrival").length : 0;

  const dateOptions = useMemo(() => { const opts = []; for (let i = 0; i < 14; i++) { const d = new Date(now); d.setDate(d.getDate() + i); d.setHours(0, 0, 0, 0); opts.push(d); } return opts; }, [now]);
  function toggleService(id) { setServiceIds(cur => cur.includes(id) ? cur.filter(x => x !== id) : [...cur, id]); }

  function slotStatus(barberIdArg, dateObj, tMin, duration) {
    const dayIdx = dateObj.getDay(); const { open, close } = getShopHours(dayIdx); const dateStr = fmtDate(dateObj);
    const isToday = fmtDate(now) === dateStr; const nowMins = now.getHours() * 60 + now.getMinutes();
    if (isToday && tMin <= nowMins + 15) return "past";
    if (tMin + duration > close) return "overflow";
    const dayBookings = bookings.filter(b => b.barberId === barberIdArg && b.date === dateStr && (b.status === "pending" || b.status === "awaiting_arrival"));
    const overlap = dayBookings.some(b => { const [bh, bm] = b.time.split(":").map(Number); const bStart = bh * 60 + bm, bEnd = bStart + b.totalDuration; return tMin < bEnd && tMin + duration > bStart; });
    return overlap ? "taken" : "free";
  }

  const allSlots = useMemo(() => {
    if (!barberId || !date) return [];
    const dayIdx = date.getDay(); const { open, close } = getShopHours(dayIdx);
    const arr = [];
    for (let m = open; m < close; m += 30) arr.push({ t: m, status: slotStatus(barberId, date, m, totalDuration) });
    return arr;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [barberId, date, bookings, totalDuration, now]);

  function findNearestSlot() {
    if (!barberId) return;
    for (let i = 0; i < 14; i++) {
      const d = new Date(now); d.setDate(d.getDate() + i); d.setHours(0, 0, 0, 0);
      if (d.getDay() === barber.offDay) continue;
      const { open, close } = getShopHours(d.getDay());
      for (let m = open; m < close; m += 30) {
        if (slotStatus(barberId, d, m, totalDuration) === "free") {
          setDate(d); setTime(minutesToLabel(m));
          showToast(t.nearestSlotFound(`${DAY_NAMES[lang][d.getDay()]} ${d.getDate()}`, minutesToLabel(m)));
          return;
        }
      }
    }
    showToast(t.nearestSlotNone, "err");
  }

  function submitBooking() {
    try {
      const booking = { id: uid(), customerUsername: currentUser.username, customerName: currentUser.fullName, wilaya, phone, note, barberId, serviceIds, date: fmtDate(date), time, totalPrice, totalDuration, status: "pending", createdAt: Date.now(), completedAt: null, rated: null };
      persistBookings([...bookings, booking]);
      persistNotifications(pushNotification(notifications, { forRole: "owner", forUsername: null, message: `${currentUser.fullName} → ${barber ? barber.name : ""} (${booking.date} ${booking.time})` }));
    } catch (e) {
      console.error("submitBooking error:", e);
    } finally {
      showToast(t.okBookingSent);
      onDone();
    }
  }

  const steps = [t.stepBarber, t.stepService, t.stepInfo, t.stepDate, t.stepTime, t.stepConfirm];

  if (hasActiveBooking) return <Card><p className="text-sm text-center" style={{ color: "#ff8a8a" }}>{t.errActiveBooking}</p></Card>;

  return (
    <div className="space-y-4 pb-4">
      <div className="flex items-center justify-between px-1">{steps.map((s, i) => <div key={s} className="flex-1 flex items-center"><div className="w-full h-1 rounded-full" style={{ background: i <= step ? "#C9A227" : "#262220" }} /></div>)}</div>
      <p className="text-xs text-center font-bold" style={{ color: "#9B9691" }}>{t.stepOf(step + 1, steps.length)}: {steps[step]}</p>

      {step === 0 && (
        <div className="space-y-2">
          <h3 className="text-sm font-extrabold" style={{ color: "#E8C468" }}>{t.chooseBarberTitle}</h3>
          {BARBERS.map(b => { const qCount = bookings.filter(x => x.barberId === b.id && x.date === todayStr && x.status === "awaiting_arrival").length; return (
            <button key={b.id} onClick={() => setBarberId(b.id)} className="w-full"><Card glow={barberId === b.id} className="flex items-center gap-3"><Avatar initials={b.initials} photo={getBarberPhoto(b.id, barberPhotos)} /><div className="text-start flex-1"><p className="font-bold text-sm">{b.name}</p><p className="text-[11px]" style={{ color: "#6b655c" }}>{t.offDayLabel}: {DAY_NAMES[lang][b.offDay]} · {t.waitingTodayShort}: {qCount}</p></div>{barberId === b.id && <Check size={18} color="#C9A227" />}</Card></button>
          );})}
          {barberId && <Card><p className="text-xs" style={{ color: "#9B9691" }}>{t.peopleWaitingAt(barberTodayQueue, barber?.name)}</p></Card>}
          <PrimaryButton disabled={!barberId} onClick={() => setStep(1)}>{t.nextBtn}</PrimaryButton>
        </div>
      )}

      {step === 1 && (
        <div className="space-y-2">
          <h3 className="text-sm font-extrabold" style={{ color: "#E8C468" }}>{t.chooseServicesTitle}</h3>
          {SERVICES.map(s => { const checked = serviceIds.includes(s.id); return (
            <button key={s.id} onClick={() => toggleService(s.id)} className="w-full"><Card glow={checked} className="flex items-center justify-between"><div className="flex items-center gap-2"><div className="w-5 h-5 rounded-md border flex items-center justify-center" style={{ borderColor: checked ? "#C9A227" : "#3a352f", background: checked ? "#C9A227" : "transparent" }}>{checked && <Check size={13} color="#0B0B0C" />}</div><span className="font-semibold text-sm">{s.name[lang]}</span></div><span className="font-bold text-sm" style={{ color: "#E8C468" }}>{s.price.toLocaleString()} {t.currency}</span></Card></button>
          );})}
          <div className="flex gap-2 pt-1"><GhostButton className="flex-1" onClick={() => setStep(0)}>{t.backBtn}</GhostButton><div className="flex-[2]"><PrimaryButton disabled={serviceIds.length === 0} onClick={() => setStep(2)}>{t.nextBtn} ({totalPrice.toLocaleString()} {t.currency})</PrimaryButton></div></div>
        </div>
      )}

      {step === 2 && (
        <div className="space-y-3">
          <h3 className="text-sm font-extrabold" style={{ color: "#E8C468" }}>{t.stepInfo}</h3>
          <Field label={t.phoneLabel} icon={<Phone size={14} color="#9B9691" />}><input className="auth-input" value={phone} onChange={e => setPhone(e.target.value)} placeholder="0550000000" /></Field>
          <Field label={t.wilayaLabel} icon={<MapPin size={14} color="#9B9691" />}><input className="auth-input" value={wilaya} onChange={e => setWilaya(e.target.value)} /></Field>
          <Field label={t.noteLabel} icon={<MessageSquare size={14} color="#9B9691" />}><textarea className="auth-input" rows={3} value={note} onChange={e => setNote(e.target.value)} /></Field>
          <div className="flex gap-2 pt-1"><GhostButton className="flex-1" onClick={() => setStep(1)}>{t.backBtn}</GhostButton><div className="flex-[2]"><PrimaryButton disabled={!phone.trim() || !wilaya.trim()} onClick={() => setStep(3)}>{t.nextBtn}</PrimaryButton></div></div>
        </div>
      )}

      {step === 3 && (
        <div className="space-y-2">
          <h3 className="text-sm font-extrabold" style={{ color: "#E8C468" }}>{t.chooseDateTitle}</h3>
          <div className="space-y-2 max-h-[380px] overflow-y-auto pr-1">
            {dateOptions.map(d => { const disabled = barber && d.getDay() === barber.offDay; const selected = date && fmtDate(date) === fmtDate(d); return (
              <button key={fmtDate(d)} disabled={disabled} onClick={() => { setDate(d); setTime(null); }} className="w-full disabled:opacity-30"><Card glow={selected} className="flex items-center justify-between"><div><p className="font-bold text-sm">{DAY_NAMES[lang][d.getDay()]}</p><p className="text-[11px]" style={{ color: "#6b655c" }}>{MONTH_NAMES[lang][d.getMonth()]} {d.getDate()}</p></div>{disabled && <span className="text-[10px] font-bold" style={{ color: "#c0392b" }}>{t.dayOffLabel}</span>}{selected && <Check size={18} color="#C9A227" />}</Card></button>
            );})}
          </div>
          <div className="flex gap-2 pt-1"><GhostButton className="flex-1" onClick={() => setStep(2)}>{t.backBtn}</GhostButton><div className="flex-[2]"><PrimaryButton disabled={!date} onClick={() => setStep(4)}>{t.nextBtn}</PrimaryButton></div></div>
        </div>
      )}

      {step === 4 && (
        <div className="space-y-2">
          <div className="flex items-center justify-between">
            <h3 className="text-sm font-extrabold" style={{ color: "#E8C468" }}>{t.chooseTimeTitle}</h3>
            <button onClick={findNearestSlot} className="text-[11px] font-bold flex items-center gap-1 px-2.5 py-1.5 rounded-full" style={{ background: "#1a1712", color: "#E8C468", border: "1px solid #C9A227" }}><Zap size={12} />{t.nearestSlotBtn}</button>
          </div>
          <div className="grid grid-cols-3 gap-2 max-h-[380px] overflow-y-auto">
            {allSlots.map(({ t: m, status }) => {
              const label = minutesToLabel(m); const isSelected = time === label; const disabled = status !== "free";
              return (
                <button key={m} onClick={() => disabled ? showToast(t.unavailableSlot, "err") : setTime(label)}>
                  <div className="rounded-xl py-3 text-center text-sm font-bold border" style={{
                    borderColor: isSelected ? "#C9A227" : "#262220",
                    background: isSelected ? "#C9A227" : disabled ? "#161414" : "#141414",
                    color: isSelected ? "#0B0B0C" : disabled ? "#544e46" : "#F5F0E6",
                    opacity: disabled ? 0.6 : 1, textDecoration: disabled ? "line-through" : "none",
                  }}>{label}</div>
                </button>
              );
            })}
          </div>
          <div className="flex gap-2 pt-1"><GhostButton className="flex-1" onClick={() => setStep(3)}>{t.backBtn}</GhostButton><div className="flex-[2]"><PrimaryButton disabled={!time} onClick={() => setStep(5)}>{t.nextBtn}</PrimaryButton></div></div>
        </div>
      )}

      {step === 5 && (
        <div className="space-y-3">
          <h3 className="text-sm font-extrabold" style={{ color: "#E8C468" }}>{t.reviewBookingTitle}</h3>
          <Card className="space-y-2">
            <Row label={t.barberLbl} value={barber?.name} />
            <Row label={t.dateLbl} value={date ? `${DAY_NAMES[lang][date.getDay()]} ${date.getDate()} ${MONTH_NAMES[lang][date.getMonth()]}` : ""} />
            <Row label={t.timeLbl} value={time} />
            <div className="h-px my-1" style={{ background: "#262220" }} />
            {chosenServices.map(s => <Row key={s.id} label={s.name[lang]} value={`${s.price.toLocaleString()} ${t.currency}`} />)}
            <div className="h-px my-1" style={{ background: "#262220" }} />
            <Row label={t.feeNote} value={`${BOOKING_FEE} ${t.currency}`} />
            <div className="h-px my-1" style={{ background: "#262220" }} />
            <Row label={t.grandTotalLbl} value={`${grandTotal.toLocaleString()} ${t.currency}`} bold />
          </Card>
          <Card><p className="text-xs leading-relaxed" style={{ color: "#9B9691" }}><AlertCircle size={13} className="inline mx-1" color="#C9A227" />{t.confirmNote}</p></Card>
          <div className="flex gap-2"><GhostButton className="flex-1" onClick={() => setStep(4)}>{t.backBtn}</GhostButton><div className="flex-[2]"><PrimaryButton onClick={submitBooking}>{t.confirmBookingBtn}</PrimaryButton></div></div>
        </div>
      )}
    </div>
  );
}


/* ---------------- قسم عرض العريس ---------------- */
function GroomSection({ now, currentUser, bookings, persistBookings, notifications, persistNotifications, pushNotification, showToast, barberPhotos, hasActiveBooking, onBack, onDone }) {
  const { t, lang } = useLang();
  const [step, setStep] = useState(0);
  const [bookingType, setBookingType] = useState(null); // groom_package | groom_custom
  const [serviceIds, setServiceIds] = useState([]);
  const [barberId, setBarberId] = useState(null);
  const [location, setLocation] = useState("shop");
  const [phone, setPhone] = useState("");
  const [address, setAddress] = useState("");
  const [venueName, setVenueName] = useState("");
  const [weddingDate, setWeddingDate] = useState("");
  const [shopVisitDate, setShopVisitDate] = useState("");
  const [notes, setNotes] = useState("");

  const chosenServices = SERVICES.filter(s => serviceIds.includes(s.id));
  const customTotal = chosenServices.reduce((s, x) => s + x.price, 0);
  const price = bookingType === "groom_package" ? GROOM_PACKAGE_PRICE : customTotal;

  const minDate = useMemo(() => { const d = new Date(now); d.setDate(d.getDate() + GROOM_MIN_DAYS); d.setHours(0, 0, 0, 0); return fmtDate(d); }, [now]);
  const dateValid = weddingDate && weddingDate >= minDate;

  function submitGroomBooking() {
    if (!dateValid) { showToast(t.groomMinDaysError, "err"); return; }
    try {
      const booking = {
        id: uid(), bookingType, customerUsername: currentUser.username, customerName: currentUser.fullName,
        barberId, serviceIds: bookingType === "groom_package" ? ["s3", "s5", "s6", "s7"] : serviceIds,
        totalPrice: price, totalDuration: 60, status: "pending", createdAt: Date.now(), completedAt: null, rated: null,
        phone, wilaya: "", note: notes, serviceLocation: location, address, venueName,
        weddingDate, shopVisitDate: location === "shop" ? "" : shopVisitDate,
        date: weddingDate, time: null,
      };
      persistBookings([...bookings, booking]);
      const barber = BARBERS.find(b => b.id === barberId);
      persistNotifications(pushNotification(notifications, { forRole: "owner", forUsername: null, message: `👑 ${currentUser.fullName} → ${barber ? barber.name : ""} (${weddingDate})` }));
    } catch (e) {
      console.error("submitGroomBooking error:", e);
    } finally {
      showToast(t.groomSentOk);
      onDone();
    }
  }

  const steps = [t.groomTitle, t.stepBarber, t.groomLocationTitle, t.stepInfo, t.stepConfirm];

  if (hasActiveBooking) return (
    <div className="space-y-3">
      <button onClick={onBack} className="text-xs font-bold" style={{ color: "#9B9691" }}>← {t.groomBackBtn}</button>
      <Card><p className="text-sm text-center" style={{ color: "#ff8a8a" }}>{t.errActiveBooking}</p></Card>
    </div>
  );

  return (
    <div className="space-y-4 pb-4">
      <button onClick={onBack} className="text-xs font-bold flex items-center gap-1" style={{ color: "#9B9691" }}><ArrowLeft size={13} style={lang !== "ar" ? { transform: "scaleX(-1)" } : {}} />{t.groomBackBtn}</button>
      <div className="flex items-center justify-between px-1">{steps.map((s, i) => <div key={s} className="flex-1 flex items-center"><div className="w-full h-1 rounded-full" style={{ background: i <= step ? "#C9A227" : "#262220" }} /></div>)}</div>

      {step === 0 && (
        <div className="space-y-3">
          <Card glow>
            <p className="font-extrabold text-base mb-1" style={{ color: "#E8C468" }}>{t.groomPackageTitle} - {t.groomPackagePrice}</p>
            <p className="text-xs leading-relaxed" style={{ color: "#9B9691" }}>{t.groomPackageDesc}</p>
          </Card>
          <PrimaryButton onClick={() => { setBookingType("groom_package"); setStep(1); }}>{t.groomChoosePackage}</PrimaryButton>
          <GhostButton className="w-full text-center" onClick={() => { setBookingType("groom_custom"); setStep(1); }}>{t.groomChooseCustom}</GhostButton>
        </div>
      )}

      {step === 1 && bookingType === "groom_custom" && serviceIds.length === 0 && (
        <div className="space-y-2">
          <h3 className="text-sm font-extrabold" style={{ color: "#E8C468" }}>{t.chooseServicesTitle}</h3>
          {SERVICES.map(s => { const checked = serviceIds.includes(s.id); return (
            <button key={s.id} onClick={() => setServiceIds(cur => cur.includes(s.id) ? cur.filter(x => x !== s.id) : [...cur, s.id])} className="w-full">
              <Card glow={checked} className="flex items-center justify-between"><div className="flex items-center gap-2"><div className="w-5 h-5 rounded-md border flex items-center justify-center" style={{ borderColor: checked ? "#C9A227" : "#3a352f", background: checked ? "#C9A227" : "transparent" }}>{checked && <Check size={13} color="#0B0B0C" />}</div><span className="font-semibold text-sm">{s.name[lang]}</span></div><span className="font-bold text-sm" style={{ color: "#E8C468" }}>{s.price.toLocaleString()} {t.currency}</span></Card>
            </button>
          );})}
        </div>
      )}

      {step === 1 && (bookingType === "groom_package" || serviceIds.length > 0) && (
        <div className="space-y-2">
          <h3 className="text-sm font-extrabold" style={{ color: "#E8C468" }}>{t.groomChooseBarberTitle}</h3>
          {BARBERS.map(b => {
            const served = bookings.filter(x => x.barberId === b.id && x.status === "completed").length;
            const pend = bookings.filter(x => x.barberId === b.id && (x.status === "pending" || x.status === "awaiting_arrival")).length;
            return (
              <button key={b.id} onClick={() => setBarberId(b.id)} className="w-full"><Card glow={barberId === b.id} className="flex items-center gap-3">
                <Avatar initials={b.initials} photo={getBarberPhoto(b.id, barberPhotos)} />
                <div className="text-start flex-1"><p className="font-bold text-sm">{b.name}</p><p className="text-[11px]" style={{ color: "#6b655c" }}>{t.groomServedLbl}: {served} · {t.groomPendingLbl}: {pend}</p></div>
                {barberId === b.id && <Check size={18} color="#C9A227" />}
              </Card></button>
            );
          })}
          <div className="flex gap-2 pt-1">
            <GhostButton className="flex-1" onClick={() => { if (bookingType === "groom_custom") setServiceIds([]); else setStep(0); }}>{t.backBtn}</GhostButton>
            <div className="flex-[2]"><PrimaryButton disabled={!barberId} onClick={() => setStep(2)}>{t.nextBtn}</PrimaryButton></div>
          </div>
        </div>
      )}

      {step === 2 && (
        <div className="space-y-2">
          <h3 className="text-sm font-extrabold" style={{ color: "#E8C468" }}>{t.groomLocationTitle}</h3>
          {[{ k: "shop", l: t.groomLocationShop }, { k: "home", l: t.groomLocationHome }, { k: "hall", l: t.groomLocationHall }].map(o => (
            <button key={o.k} onClick={() => setLocation(o.k)} className="w-full"><Card glow={location === o.k} className="flex items-center justify-between"><span className="font-semibold text-sm">{o.l}</span>{location === o.k && <Check size={18} color="#C9A227" />}</Card></button>
          ))}
          <div className="flex gap-2 pt-1"><GhostButton className="flex-1" onClick={() => setStep(1)}>{t.backBtn}</GhostButton><div className="flex-[2]"><PrimaryButton onClick={() => setStep(3)}>{t.nextBtn}</PrimaryButton></div></div>
        </div>
      )}

      {step === 3 && (
        <div className="space-y-3">
          <h3 className="text-sm font-extrabold" style={{ color: "#E8C468" }}>{t.stepInfo}</h3>
          <Field label={t.groomPhoneLabel} icon={<Phone size={14} color="#9B9691" />}><input className="auth-input" value={phone} onChange={e => setPhone(e.target.value)} placeholder="0550000000" /></Field>
          <Field label={t.groomWeddingDayLabel} icon={<Calendar size={14} color="#9B9691" />}>
            <input type="date" className="auth-input" min={minDate} value={weddingDate} onChange={e => setWeddingDate(e.target.value)} />
          </Field>
          {!dateValid && weddingDate && <p className="text-xs font-bold" style={{ color: "#ff8a8a" }}>{t.groomMinDaysError}</p>}
          {location !== "shop" && (
            <>
              <Field label={t.groomAddressLabel} icon={<MapPin size={14} color="#9B9691" />}><input className="auth-input" value={address} onChange={e => setAddress(e.target.value)} /></Field>
              <Field label={t.groomVenueLabel} icon={<MapPin size={14} color="#9B9691" />}><input className="auth-input" value={venueName} onChange={e => setVenueName(e.target.value)} /></Field>
              <Field label={t.groomShopVisitLabel} icon={<Calendar size={14} color="#9B9691" />}><input type="date" className="auth-input" min={minDate} value={shopVisitDate} onChange={e => setShopVisitDate(e.target.value)} /></Field>
            </>
          )}
          <Field label={t.groomNotesLabel} icon={<MessageSquare size={14} color="#9B9691" />}><textarea className="auth-input" rows={3} value={notes} onChange={e => setNotes(e.target.value)} /></Field>
          <div className="flex gap-2 pt-1"><GhostButton className="flex-1" onClick={() => setStep(2)}>{t.backBtn}</GhostButton><div className="flex-[2]"><PrimaryButton disabled={!phone.trim() || !dateValid} onClick={() => setStep(4)}>{t.nextBtn}</PrimaryButton></div></div>
        </div>
      )}

      {step === 4 && (
        <div className="space-y-3">
          <h3 className="text-sm font-extrabold" style={{ color: "#E8C468" }}>{t.groomReviewTitle}</h3>
          <Card className="space-y-2">
            <Row label={t.groomTypeLbl} value={bookingType === "groom_package" ? t.groomTypePackage : t.groomTypeCustom} />
            <Row label={t.barberLbl} value={BARBERS.find(b => b.id === barberId)?.name} />
            <Row label={t.groomWeddingDayLabel} value={weddingDate} />
            <Row label={t.groomLocationTitle} value={location === "shop" ? t.groomLocationShop : location === "home" ? t.groomLocationHome : t.groomLocationHall} />
            {location !== "shop" && <Row label={t.groomAddressLabel} value={address} />}
            <div className="h-px my-1" style={{ background: "#262220" }} />
            {bookingType === "groom_package" ? <Row label={t.groomPackageTitle} value={t.groomPackagePrice} /> : chosenServices.map(s => <Row key={s.id} label={s.name[lang]} value={`${s.price.toLocaleString()} ${t.currency}`} />)}
            <div className="h-px my-1" style={{ background: "#262220" }} />
            <Row label={t.feeNote} value={`${BOOKING_FEE} ${t.currency}`} />
            <div className="h-px my-1" style={{ background: "#262220" }} />
            <Row label={t.grandTotalLbl} value={`${(price + BOOKING_FEE).toLocaleString()} ${t.currency}`} bold />
          </Card>
          <Card><p className="text-xs leading-relaxed" style={{ color: "#9B9691" }}><AlertCircle size={13} className="inline mx-1" color="#C9A227" />{t.groomTimeNote}</p></Card>
          <div className="flex gap-2"><GhostButton className="flex-1" onClick={() => setStep(3)}>{t.backBtn}</GhostButton><div className="flex-[2]"><PrimaryButton onClick={submitGroomBooking}>{t.groomConfirmBtn}</PrimaryButton></div></div>
        </div>
      )}
    </div>
  );
}

function AccountSection({ currentUser, upcoming, past, bookings, onCancel, users, persistUsers, showToast }) {
  const { t } = useLang();
  const loyalty = currentUser.loyaltyCount || 0; const progress = loyalty % LOYALTY_TARGET; const freeHaircuts = Math.floor(loyalty / LOYALTY_TARGET); const missed = currentUser.missedCount || 0;
  function queuePosition(b) {
    if (b.status !== "awaiting_arrival") return null;
    const [h, m] = b.time.split(":").map(Number); const myMins = h * 60 + m;
    return bookings.filter(x => x.barberId === b.barberId && x.date === b.date && x.status === "awaiting_arrival" && x.id !== b.id).filter(x => { const [xh, xm] = x.time.split(":").map(Number); return xh * 60 + xm < myMins; }).length;
  }
  async function handleAvatarChange(e) {
    const file = e.target.files && e.target.files[0];
    if (!file) return;
    try {
      const dataUrl = await fileToDataUrl(file);
      persistUsers(users.map(u => u.username === currentUser.username ? { ...u, avatarDataUrl: dataUrl } : u));
      showToast(t.photoUpdated);
    } catch { showToast(t.photoUpdateFailed, "err"); }
  }
  return (
    <div className="space-y-4 pb-4">
      <div className="text-center py-2">
        <div className="relative inline-block">
          <Avatar photo={currentUser.avatarDataUrl} initials={currentUser.fullName.split(" ").map(w => w[0]).join("").slice(0, 2).toUpperCase()} size={64} />
          <label className="absolute -bottom-1 -left-1 w-6 h-6 rounded-full flex items-center justify-center cursor-pointer" style={{ background: "#C9A227", border: "2px solid #0B0B0C" }}>
            <Camera size={12} color="#0B0B0C" />
            <input type="file" accept="image/*" className="hidden" onChange={handleAvatarChange} />
          </label>
        </div>
        <h2 className="text-lg font-extrabold mt-2">{currentUser.fullName}</h2><p className="text-xs" style={{ color: "#6b655c" }}>@{currentUser.username}</p>
      </div>
      <div className="grid grid-cols-2 gap-3">
        <Card className="text-center"><p className="text-lg font-extrabold" style={{ color: "#7be08a" }}>{loyalty}</p><p className="text-[10px] mt-1" style={{ color: "#9B9691" }}>{t.completedServicesLbl}</p></Card>
        <Card className="text-center"><p className="text-lg font-extrabold" style={{ color: "#ff8a8a" }}>{missed}</p><p className="text-[10px] mt-1" style={{ color: "#9B9691" }}>{t.missedBookingsLbl}</p></Card>
      </div>
      <Section title={t.loyaltyTitle}>
        <Card>
          <div className="flex items-center justify-between mb-2"><span className="text-sm font-bold flex items-center gap-1"><Award size={15} color="#C9A227" />{t.loyaltyDesc}</span><span className="text-sm font-extrabold" style={{ color: "#E8C468" }}>{progress}/{LOYALTY_TARGET}</span></div>
          <div className="h-2 rounded-full overflow-hidden" style={{ background: "#262220" }}><div className="h-full rounded-full" style={{ width: `${(progress / LOYALTY_TARGET) * 100}%`, background: "linear-gradient(90deg,#C9A227,#E8C468)" }} /></div>
          {freeHaircuts > 0 && <p className="text-xs mt-2 font-bold" style={{ color: "#7be08a" }}>{t.freeHaircutMsg(freeHaircuts)}</p>}
        </Card>
      </Section>
      <Section title={t.upcomingTitle}>{upcoming.length === 0 ? <EmptyMsg text={t.noUpcoming} /> : <div className="space-y-2">{upcoming.map(b => <BookingCard key={b.id} b={b} queuePos={queuePosition(b)} onCancel={() => onCancel(b.id)} />)}</div>}</Section>
      <Section title={t.pastTitle}>{past.length === 0 ? <EmptyMsg text={t.noPast} /> : <div className="space-y-2">{past.map(b => <BookingCard key={b.id} b={b} />)}</div>}</Section>
    </div>
  );
}

function BookingCard({ b, queuePos, onCancel }) {
  const { t, lang } = useLang();
  const barber = BARBERS.find(x => x.id === b.barberId);
  const services = SERVICES.filter(s => b.serviceIds.includes(s.id));
  const st = statusLabel(t, b.status);
  return (
    <Card>
      <div className="flex items-center justify-between mb-2"><p className="font-bold text-sm">{barber?.name} · {b.date} {b.time}</p><span className="text-[10px] font-bold px-2 py-0.5 rounded-full" style={{ color: st.color, background: "rgba(255,255,255,0.05)" }}>{st.label}</span></div>
      <p className="text-xs" style={{ color: "#9B9691" }}>{services.map(s => s.name[lang]).join("، ")}</p>
      <p className="text-xs font-bold mt-1" style={{ color: "#E8C468" }}>{(b.totalPrice + BOOKING_FEE).toLocaleString()} {t.currency}</p>
      {queuePos !== null && queuePos !== undefined && <p className="text-xs mt-1.5" style={{ color: "#4ba3e8" }}>{t.peopleBeforeYou(barber?.name, queuePos)}</p>}
      {onCancel && <button onClick={onCancel} className="text-xs font-bold mt-2" style={{ color: "#ff8a8a" }}>{t.cancelBookingBtn}</button>}
    </Card>
  );
}

function RatingModal({ onSubmit }) {
  const { t } = useLang();
  const [rating, setRating] = useState(5); const [comment, setComment] = useState("");
  return (
    <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center p-4" style={{ background: "rgba(0,0,0,0.7)" }}>
      <div className="w-full max-w-sm rounded-2xl p-5" style={{ background: "#141414", border: "1px solid #C9A227" }}>
        <h3 className="text-lg font-extrabold text-center mb-1" style={{ fontFamily: "'Playfair Display',serif", color: "#E8C468" }}>{t.ratingModalTitle}</h3>
        <p className="text-xs text-center mb-4" style={{ color: "#9B9691" }}>{t.ratingModalSub}</p>
        <div className="flex justify-center gap-1 mb-4">{[1, 2, 3, 4, 5].map(i => <button key={i} onClick={() => setRating(i)}><Star size={30} fill={i <= rating ? "#C9A227" : "none"} color="#C9A227" /></button>)}</div>
        <textarea className="auth-input mb-3" rows={3} placeholder={t.ratingPlaceholder} value={comment} onChange={e => setComment(e.target.value)} />
        <PrimaryButton onClick={() => onSubmit(rating, comment)}>{t.submitRatingBtn}</PrimaryButton>
      </div>
    </div>
  );
}

/* ============================================================
   تطبيق الحلاق
============================================================ */
function BarberApp({ now, isShopOpenNow, barber, bookings, persistBookings, users, persistUsers, notifications, persistNotifications, pushNotification, barberPhotos, persistBarberPhotos, tab, setTab, onLogout, showToast }) {
  const { t } = useLang();
  const [showNotif, setShowNotif] = useState(false);
  const myNotifs = notifications.filter(n => n.forRole === "barber" && n.forUsername === barber.id);
  const myBookings = bookings.filter(b => b.barberId === barber.id);
  function openNotif() { setShowNotif(true); persistNotifications(notifications.map(n => (n.forRole === "barber" && n.forUsername === barber.id) ? { ...n, read: true } : n)); }

  function approveOwn(id) {
    const bk = bookings.find(b => b.id === id);
    persistBookings(bookings.map(b => b.id === id ? { ...b, status: "awaiting_arrival" } : b));
    persistNotifications(pushNotification(notifications, { forRole: "customer", forUsername: bk.customerUsername, message: `${t.okApproved}: ${bk.date} ${bk.time}` }));
    persistNotifications(pushNotification(notifications, { forRole: "owner", forUsername: null, message: `${barber.name} → ${t.okApproved}: ${bk.customerName} (${bk.date} ${bk.time})` }));
    showToast(t.okApproved);
  }
  function rejectOwn(id) {
    const bk = bookings.find(b => b.id === id);
    persistBookings(bookings.filter(b => b.id !== id));
    persistNotifications(pushNotification(notifications, { forRole: "customer", forUsername: bk.customerUsername, message: `${t.okRejected}: ${bk.date}` }));
    persistNotifications(pushNotification(notifications, { forRole: "owner", forUsername: null, message: `${barber.name} → ${t.okRejected}: ${bk.customerName}` }));
    showToast(t.okRejected);
  }
  function completeBooking(id) {
    const bk = bookings.find(b => b.id === id);
    persistBookings(bookings.map(b => b.id === id ? { ...b, status: "completed", completedAt: Date.now(), rated: false } : b));
    persistUsers(users.map(u => u.username === bk.customerUsername ? { ...u, loyaltyCount: (u.loyaltyCount || 0) + 1 } : u));
    persistNotifications(pushNotification(notifications, { forRole: "customer", forUsername: bk.customerUsername, message: `${barber.name}: ${t.statusCompleted}` }));
    showToast(t.okCompleted);
  }
  function noShowBooking(id) {
    const bk = bookings.find(b => b.id === id);
    persistBookings(bookings.map(b => b.id === id ? { ...b, status: "no_show" } : b));
    persistUsers(users.map(u => u.username === bk.customerUsername ? { ...u, missedCount: (u.missedCount || 0) + 1 } : u));
    showToast(t.okNoShow);
  }
  function cancelAccepted(id) {
    const bk = bookings.find(b => b.id === id);
    persistBookings(bookings.filter(b => b.id !== id));
    persistNotifications(pushNotification(notifications, { forRole: "customer", forUsername: bk.customerUsername, message: `${barber.name}: ${t.okCancelledByBarber}` }));
    showToast(t.okCancelledByBarber);
  }

  const navItems = [{ key: "home", label: t.navMyPanel, icon: TrendingUp }, { key: "bookings", label: t.navMySchedule, icon: Calendar }];

  return (
    <div className="pb-20">
      <TopBar subtitle={`${barber.name}`} onLogout={onLogout} notifList={myNotifs} onOpenNotif={openNotif} isShopOpenNow={isShopOpenNow} />
      {showNotif && <NotifModal list={myNotifs} onClose={() => setShowNotif(false)} />}
      <div className="px-4 pt-4 max-w-md mx-auto">
        {tab === "home" && <BarberDashboard barber={barber} bookings={myBookings} barberPhotos={barberPhotos} persistBarberPhotos={persistBarberPhotos} showToast={showToast} />}
        {tab === "bookings" && <BarberBookings now={now} bookings={myBookings} onApprove={approveOwn} onReject={rejectOwn} onComplete={completeBooking} onNoShow={noShowBooking} onCancel={cancelAccepted} />}
      </div>
      <BottomNav items={navItems} tab={tab} setTab={setTab} />
    </div>
  );
}

function BarberDashboard({ barber, bookings, barberPhotos, persistBarberPhotos, showToast }) {
  const { t } = useLang();
  const completed = bookings.filter(b => b.status === "completed");
  const startOfDay = new Date(); startOfDay.setHours(0, 0, 0, 0);
  const startOfWeek = new Date(startOfDay); startOfWeek.setDate(startOfWeek.getDate() - startOfWeek.getDay());
  const startOfMonth = new Date(startOfDay.getFullYear(), startOfDay.getMonth(), 1);
  const revenueSince = d => completed.filter(b => b.completedAt >= d.getTime()).reduce((s, b) => s + b.totalPrice, 0);
  const uniqueCustomers = new Set(completed.map(b => b.customerUsername)).size;
  const todayStr = fmtDate(new Date()); const waitingToday = bookings.filter(b => b.status === "awaiting_arrival" && b.date === todayStr).length;
  async function handlePhotoChange(e) {
    const file = e.target.files && e.target.files[0];
    if (!file) return;
    try {
      const dataUrl = await fileToDataUrl(file);
      persistBarberPhotos({ ...barberPhotos, [barber.id]: dataUrl });
      showToast(t.photoUpdated);
    } catch { showToast(t.photoUpdateFailed, "err"); }
  }
  return (
    <div className="space-y-4 pb-4">
      <div className="text-center py-2">
        <div className="relative inline-block">
          <Avatar photo={getBarberPhoto(barber.id, barberPhotos)} initials={barber.initials} size={72} />
          <label className="absolute -bottom-1 -left-1 w-7 h-7 rounded-full flex items-center justify-center cursor-pointer" style={{ background: "#C9A227", border: "2px solid #0B0B0C" }}>
            <Camera size={13} color="#0B0B0C" />
            <input type="file" accept="image/*" className="hidden" onChange={handlePhotoChange} />
          </label>
        </div>
        <h2 className="text-lg font-extrabold mt-2">{barber.name}</h2>
      </div>
      <div className="grid grid-cols-2 gap-3">
        <StatCard label={t.earningsToday} value={`${revenueSince(startOfDay).toLocaleString()} ${t.currency}`} />
        <StatCard label={t.earningsWeek} value={`${revenueSince(startOfWeek).toLocaleString()} ${t.currency}`} />
        <StatCard label={t.earningsMonth} value={`${revenueSince(startOfMonth).toLocaleString()} ${t.currency}`} />
        <StatCard label={t.earningsAll} value={`${completed.reduce((s, b) => s + b.totalPrice, 0).toLocaleString()} ${t.currency}`} />
      </div>
      <div className="grid grid-cols-2 gap-3"><StatCard label={t.myTotalCustomers} value={uniqueCustomers} small /><StatCard label={t.waitingTodayLbl} value={waitingToday} small /></div>
    </div>
  );
}

function BarberBookings({ now, bookings, onApprove, onReject, onComplete, onNoShow, onCancel }) {
  const { t, lang } = useLang();
  const [subTab, setSubTab] = useState("awaiting");
  const pending = bookings.filter(b => b.status === "pending"); const awaiting = bookings.filter(b => b.status === "awaiting_arrival");
  const completed = bookings.filter(b => b.status === "completed"); const noShow = bookings.filter(b => b.status === "no_show");
  const tabs = [{ key: "pending", label: t.tabPendingApproval(pending.length) }, { key: "awaiting", label: t.tabMySchedule(awaiting.length) }, { key: "completed", label: t.tabServedByMe(completed.length) }, { key: "no_show", label: t.tabNoShowMine(noShow.length) }];
  return (
    <div className="space-y-3 pb-4">
      <div className="flex gap-2 overflow-x-auto pb-1">{tabs.map(tb => <button key={tb.key} onClick={() => setSubTab(tb.key)} className="whitespace-nowrap rounded-full px-3 py-1.5 text-xs font-bold border" style={{ borderColor: subTab === tb.key ? "#C9A227" : "#262220", background: subTab === tb.key ? "#C9A227" : "transparent", color: subTab === tb.key ? "#0B0B0C" : "#9B9691" }}>{tb.label}</button>)}</div>
      {subTab === "pending" && (pending.length === 0 ? <EmptyMsg /> : pending.map(b => (
        <OwnerBookingCard key={b.id} b={b}>
          <div className="flex gap-2 mt-3">
            <button onClick={() => onReject(b.id)} className="flex-1 rounded-xl py-2.5 font-bold text-sm flex items-center justify-center gap-1" style={{ background: "#2a1414", color: "#ff8a8a" }}><X size={15} />{t.rejectBtn}</button>
            <button onClick={() => onApprove(b.id)} className="flex-1 rounded-xl py-2.5 font-bold text-sm flex items-center justify-center gap-1" style={{ background: "#132a17", color: "#7be08a" }}><Check size={15} />{t.approveBtn}</button>
          </div>
        </OwnerBookingCard>
      )))}
      {subTab === "awaiting" && (awaiting.length === 0 ? <EmptyMsg /> : awaiting.map(b => {
        const bTime = new Date(`${b.date}T${b.time}:00`); const isDue = now.getTime() >= bTime.getTime();
        return (
          <OwnerBookingCard key={b.id} b={b} highlight={isDue}>
            {isDue ? (
              <div className="mt-3"><p className="text-xs font-bold mb-2" style={{ color: "#C9A227" }}>{t.dueNowMsgBarber}</p>
                <div className="flex gap-2"><button onClick={() => onNoShow(b.id)} className="flex-1 rounded-xl py-2.5 font-bold text-sm flex items-center justify-center gap-1" style={{ background: "#2a1414", color: "#ff8a8a" }}><XCircle size={15} />{t.noShowBtn}</button><button onClick={() => onComplete(b.id)} className="flex-1 rounded-xl py-2.5 font-bold text-sm flex items-center justify-center gap-1" style={{ background: "#132a17", color: "#7be08a" }}><CheckCircle2 size={15} />{t.completeServiceBtn}</button></div>
              </div>
            ) : (
              <button onClick={() => onCancel(b.id)} className="text-xs font-bold mt-2" style={{ color: "#ff8a8a" }}>{t.barberCancelBtn}</button>
            )}
          </OwnerBookingCard>
        );
      }))}
      {subTab === "completed" && (completed.length === 0 ? <EmptyMsg /> : completed.map(b => <OwnerBookingCard key={b.id} b={b} />))}
      {subTab === "no_show" && (noShow.length === 0 ? <EmptyMsg /> : noShow.map(b => <OwnerBookingCard key={b.id} b={b} />))}
    </div>
  );
}

/* ============================================================
   تطبيق صاحب المحل
============================================================ */
function OwnerApp({ now, isShopOpenNow, shopStatus, persistShopStatus, bookings, persistBookings, users, persistUsers, reviews, notifications, persistNotifications, pushNotification, barberPhotos, persistBarberPhotos, tab, setTab, onLogout, showToast }) {
  const { t } = useLang();
  const [showNotif, setShowNotif] = useState(false);
  const myNotifs = notifications.filter(n => n.forRole === "owner");
  const navItems = [{ key: "home", label: t.navDashboard, icon: TrendingUp }, { key: "bookings", label: t.navBookings, icon: Calendar }, { key: "grooms", label: t.navGrooms, icon: Crown }, { key: "barbers", label: t.navBarbers, icon: Users }];
  function openNotif() { setShowNotif(true); persistNotifications(notifications.map(n => n.forRole === "owner" ? { ...n, read: true } : n)); }

  function approve(id) {
    const bk = bookings.find(b => b.id === id);
    persistBookings(bookings.map(b => b.id === id ? { ...b, status: "awaiting_arrival" } : b));
    let notifs = pushNotification(notifications, { forRole: "customer", forUsername: bk.customerUsername, message: `${t.okApproved}: ${bk.date} ${bk.time}` });
    notifs = pushNotification(notifs, { forRole: "barber", forUsername: bk.barberId, message: `${bk.customerName}: ${bk.date} ${bk.time}` });
    persistNotifications(notifs); showToast(t.okApproved);
  }
  function reject(id) {
    const bk = bookings.find(b => b.id === id);
    persistBookings(bookings.filter(b => b.id !== id));
    persistNotifications(pushNotification(notifications, { forRole: "customer", forUsername: bk.customerUsername, message: `${t.okRejected}: ${bk.date}` }));
    showToast(t.okRejected);
  }
  function completeBooking(id) {
    const bk = bookings.find(b => b.id === id);
    persistBookings(bookings.map(b => b.id === id ? { ...b, status: "completed", completedAt: Date.now(), rated: false } : b));
    persistUsers(users.map(u => u.username === bk.customerUsername ? { ...u, loyaltyCount: (u.loyaltyCount || 0) + 1 } : u));
    showToast(t.okCompleted);
  }
  function noShowBooking(id) {
    const bk = bookings.find(b => b.id === id);
    persistBookings(bookings.map(b => b.id === id ? { ...b, status: "no_show" } : b));
    persistUsers(users.map(u => u.username === bk.customerUsername ? { ...u, missedCount: (u.missedCount || 0) + 1 } : u));
    showToast(t.okNoShow);
  }
  function ownerCancelAccepted(id) {
    const bk = bookings.find(b => b.id === id);
    persistBookings(bookings.filter(b => b.id !== id));
    persistNotifications(pushNotification(notifications, { forRole: "customer", forUsername: bk.customerUsername, message: `${t.okCancelledByBarber}: ${bk.date} ${bk.time}` }));
    if (bk.barberId) persistNotifications(pushNotification(notifications, { forRole: "barber", forUsername: bk.barberId, message: `${t.okCancelledByBarber}: ${bk.customerName} (${bk.date} ${bk.time})` }));
    showToast(t.okCancelledByBarber);
  }

  const pending = bookings.filter(b => b.status === "pending"); const awaiting = bookings.filter(b => b.status === "awaiting_arrival");
  const completed = bookings.filter(b => b.status === "completed"); const noShow = bookings.filter(b => b.status === "no_show");

  return (
    <div className="pb-20">
      <TopBar subtitle={t.roleOwner} onLogout={onLogout} notifList={myNotifs} onOpenNotif={openNotif} isShopOpenNow={isShopOpenNow} />
      {showNotif && <NotifModal list={myNotifs} onClose={() => setShowNotif(false)} />}
      <div className="px-4 pt-4 max-w-md mx-auto">
        {tab === "home" && <OwnerDashboard completed={completed} pending={pending} awaiting={awaiting} reviews={reviews} users={users} shopStatus={shopStatus} persistShopStatus={persistShopStatus} />}
        {tab === "bookings" && <OwnerBookings now={now} pending={pending} awaiting={awaiting} completed={completed} noShow={noShow} approve={approve} reject={reject} onComplete={completeBooking} onNoShow={noShowBooking} onCancel={ownerCancelAccepted} />}
        {tab === "grooms" && <OwnerGrooms bookings={bookings} approve={approve} reject={reject} onComplete={completeBooking} onNoShow={noShowBooking} onCancel={ownerCancelAccepted} persistBookings={persistBookings} showToast={showToast} />}
        {tab === "barbers" && <OwnerBarbers bookings={bookings} barberPhotos={barberPhotos} persistBarberPhotos={persistBarberPhotos} showToast={showToast} />}
      </div>
      <BottomNav items={navItems} tab={tab} setTab={setTab} />
    </div>
  );
}

function OwnerDashboard({ completed, pending, awaiting, reviews, users, shopStatus, persistShopStatus }) {
  const { t } = useLang();
  const startOfDay = new Date(); startOfDay.setHours(0, 0, 0, 0);
  const startOfWeek = new Date(startOfDay); startOfWeek.setDate(startOfWeek.getDate() - startOfWeek.getDay());
  const startOfMonth = new Date(startOfDay.getFullYear(), startOfDay.getMonth(), 1);
  const revenueSince = (date) => completed.filter(b => b.completedAt >= date.getTime()).reduce((s, b) => s + b.totalPrice + BOOKING_FEE, 0);
  const todayRev = revenueSince(startOfDay), weekRev = revenueSince(startOfWeek), monthRev = revenueSince(startOfMonth);
  const allRev = completed.reduce((s, b) => s + b.totalPrice + BOOKING_FEE, 0);
  const avgRating = reviews.length ? (reviews.reduce((s, r) => s + r.rating, 0) / reviews.length).toFixed(1) : "0.0";

  const statusOpts = [{ key: null, label: t.shopStatusAuto }, { key: true, label: t.shopStatusForceOpen }, { key: false, label: t.shopStatusForceClosed }];

  return (
    <div className="space-y-4 pb-4">
      <Card>
        <p className="text-xs font-extrabold mb-2 flex items-center gap-1.5" style={{ color: "#E8C468" }}><Power size={14} />{t.shopStatusTitle}</p>
        <div className="grid grid-cols-3 gap-1.5">
          {statusOpts.map(o => (<button key={String(o.key)} onClick={() => persistShopStatus({ override: o.key })} className="rounded-lg py-2 text-[10px] font-bold border" style={{ borderColor: shopStatus.override === o.key ? "#C9A227" : "#3a352f", background: shopStatus.override === o.key ? "#C9A227" : "transparent", color: shopStatus.override === o.key ? "#0B0B0C" : "#9B9691" }}>{o.label}</button>))}
        </div>
      </Card>
      <div className="grid grid-cols-2 gap-3">
        <StatCard label={t.earningsToday} value={`${todayRev.toLocaleString()} ${t.currency}`} icon={<Wallet size={16} color="#C9A227" />} />
        <StatCard label={t.earningsWeek} value={`${weekRev.toLocaleString()} ${t.currency}`} icon={<Wallet size={16} color="#C9A227" />} />
        <StatCard label={t.earningsMonth} value={`${monthRev.toLocaleString()} ${t.currency}`} icon={<Wallet size={16} color="#C9A227" />} />
        <StatCard label={t.earningsAll} value={`${allRev.toLocaleString()} ${t.currency}`} icon={<Wallet size={16} color="#C9A227" />} />
      </div>
      <div className="grid grid-cols-2 gap-2">
        <StatCard label={t.newRequests} value={pending.length} small />
        <StatCard label={t.awaitingArrivalCount} value={awaiting.length} small />
        <StatCard label={t.overallRating} value={`${avgRating} ★`} small />
        <StatCard label={t.registeredCustomers} value={users.length} small />
      </div>
      {pending.length > 0 && <Card glow><p className="text-sm font-extrabold flex items-center gap-1.5" style={{ color: "#E8C468" }}><AlertCircle size={16} />{t.pendingReqBanner(pending.length)}</p></Card>}
    </div>
  );
}

function StatCard({ label, value, icon, small }) {
  return (<Card className="text-center">{icon && <div className="flex justify-center mb-1">{icon}</div>}<p className={`font-extrabold ${small ? "text-lg" : "text-xl"}`} style={{ color: "#E8C468" }}>{value}</p><p className="text-[11px] mt-0.5" style={{ color: "#9B9691" }}>{label}</p></Card>);
}

function OwnerBookings({ now, pending, awaiting, completed, noShow, approve, reject, onComplete, onNoShow, onCancel }) {
  const { t } = useLang();
  const [subTab, setSubTab] = useState("pending");
  const tabs = [{ key: "pending", label: t.tabNewRequests(pending.length) }, { key: "awaiting", label: t.tabAwaiting(awaiting.length) }, { key: "completed", label: t.tabCompleted(completed.length) }, { key: "no_show", label: t.tabNoShow(noShow.length) }];
  return (
    <div className="space-y-3 pb-4">
      <div className="flex gap-2 overflow-x-auto pb-1">{tabs.map(tb => <button key={tb.key} onClick={() => setSubTab(tb.key)} className="whitespace-nowrap rounded-full px-3 py-1.5 text-xs font-bold border" style={{ borderColor: subTab === tb.key ? "#C9A227" : "#262220", background: subTab === tb.key ? "#C9A227" : "transparent", color: subTab === tb.key ? "#0B0B0C" : "#9B9691" }}>{tb.label}</button>)}</div>
      {subTab === "pending" && (pending.length === 0 ? <EmptyMsg /> : pending.map(b => (<OwnerBookingCard key={b.id} b={b}><div className="flex gap-2 mt-3"><button onClick={() => reject(b.id)} className="flex-1 rounded-xl py-2.5 font-bold text-sm flex items-center justify-center gap-1" style={{ background: "#2a1414", color: "#ff8a8a" }}><X size={15} />{t.rejectBtn}</button><button onClick={() => approve(b.id)} className="flex-1 rounded-xl py-2.5 font-bold text-sm flex items-center justify-center gap-1" style={{ background: "#132a17", color: "#7be08a" }}><Check size={15} />{t.approveBtn}</button></div></OwnerBookingCard>)))}
      {subTab === "awaiting" && (awaiting.length === 0 ? <EmptyMsg /> : awaiting.map(b => { const bTime = new Date(`${b.date}T${b.time}:00`); const isDue = now.getTime() >= bTime.getTime(); return (<OwnerBookingCard key={b.id} b={b} highlight={isDue}>{isDue ? (<div className="mt-3"><p className="text-xs font-bold mb-2" style={{ color: "#C9A227" }}>{t.dueNowMsg}</p><div className="flex gap-2"><button onClick={() => onNoShow(b.id)} className="flex-1 rounded-xl py-2.5 font-bold text-sm flex items-center justify-center gap-1" style={{ background: "#2a1414", color: "#ff8a8a" }}><XCircle size={15} />{t.noShowBtn}</button><button onClick={() => onComplete(b.id)} className="flex-1 rounded-xl py-2.5 font-bold text-sm flex items-center justify-center gap-1" style={{ background: "#132a17", color: "#7be08a" }}><CheckCircle2 size={15} />{t.completeServiceBtn}</button></div></div>) : (<button onClick={() => onCancel(b.id)} className="text-xs font-bold mt-2" style={{ color: "#ff8a8a" }}>{t.barberCancelBtn}</button>)}</OwnerBookingCard>); }))}
      {subTab === "completed" && (completed.length === 0 ? <EmptyMsg /> : completed.map(b => <OwnerBookingCard key={b.id} b={b} />))}
      {subTab === "no_show" && (noShow.length === 0 ? <EmptyMsg /> : noShow.map(b => <OwnerBookingCard key={b.id} b={b} />))}
    </div>
  );
}

function OwnerBookingCard({ b, children, highlight }) {
  const { t, lang } = useLang();
  const barber = BARBERS.find(x => x.id === b.barberId);
  const services = SERVICES.filter(s => b.serviceIds.includes(s.id));
  const isGroom = !!b.bookingType;
  return (
    <Card glow={highlight}>
      <div className="flex items-center justify-between mb-1">
        <p className="font-bold text-sm flex items-center gap-1">{isGroom && <Crown size={13} color="#E8C468" />}{b.customerName}</p>
        <span className="text-[11px] font-bold" style={{ color: "#E8C468" }}>{b.date}{b.time ? ` · ${b.time}` : ""}</span>
      </div>
      <p className="text-xs" style={{ color: "#9B9691" }}>{barber?.name} · {isGroom ? (b.bookingType === "groom_package" ? t.groomTypePackage : t.groomTypeCustom) : ""} {services.map(s => s.name[lang]).join("، ")}</p>
      <div className="flex items-center gap-3 mt-1.5 text-xs" style={{ color: "#6b655c" }}><span className="flex items-center gap-1"><Phone size={11} />{b.phone}</span>{!isGroom && <span className="flex items-center gap-1"><MapPin size={11} />{b.wilaya}</span>}</div>
      {isGroom && (
        <div className="mt-1.5 space-y-0.5 text-xs" style={{ color: "#9B9691" }}>
          <p>{t.groomLocationTitle}: {b.serviceLocation === "shop" ? t.groomLocationShop : b.serviceLocation === "home" ? t.groomLocationHome : t.groomLocationHall}</p>
          {b.serviceLocation !== "shop" && b.address && <p>{t.groomAddressLabel}: {b.address} {b.venueName ? `(${b.venueName})` : ""}</p>}
          {b.serviceLocation !== "shop" && b.shopVisitDate && <p>{t.groomShopVisitLabel}: {b.shopVisitDate}</p>}
          <p>{t.groomCreatedAtLbl}: {new Date(b.createdAt).toLocaleDateString()}</p>
        </div>
      )}
      {b.note && <p className="text-xs mt-1 italic" style={{ color: "#6b655c" }}>{b.note}</p>}
      <p className="text-xs font-bold mt-1.5" style={{ color: "#E8C468" }}>{(b.totalPrice + BOOKING_FEE).toLocaleString()} {t.currency}</p>
      {children}
    </Card>
  );
}

function OwnerGrooms({ bookings, approve, reject, onComplete, onNoShow, onCancel, persistBookings, showToast }) {
  const { t } = useLang();
  const groomBookings = bookings.filter(b => !!b.bookingType);
  const [timeInputs, setTimeInputs] = useState({});
  function saveTime(id) {
    const val = timeInputs[id];
    if (!val) return;
    persistBookings(bookings.map(b => b.id === id ? { ...b, time: val } : b));
    showToast(t.groomTimeSaved);
  }
  return (
    <div className="space-y-3 pb-4">
      <h3 className="text-sm font-extrabold" style={{ color: "#E8C468" }}>{t.groomBookingsTitle}</h3>
      {groomBookings.length === 0 ? <EmptyMsg text={t.noGroomBookings} /> : groomBookings.map(b => (
        <OwnerBookingCard key={b.id} b={b}>
          <div className="mt-3 flex items-center gap-2">
            <input type="time" className="auth-input flex-1" value={timeInputs[b.id] || b.time || ""} onChange={e => setTimeInputs({ ...timeInputs, [b.id]: e.target.value })} />
            <button onClick={() => saveTime(b.id)} className="rounded-lg px-3 py-2 text-xs font-bold" style={{ background: "#C9A227", color: "#0B0B0C" }}>{t.groomSetTimeBtn}</button>
          </div>
          {b.status === "pending" && (
            <div className="flex gap-2 mt-2">
              <button onClick={() => reject(b.id)} className="flex-1 rounded-xl py-2.5 font-bold text-sm flex items-center justify-center gap-1" style={{ background: "#2a1414", color: "#ff8a8a" }}><X size={15} />{t.rejectBtn}</button>
              <button onClick={() => approve(b.id)} className="flex-1 rounded-xl py-2.5 font-bold text-sm flex items-center justify-center gap-1" style={{ background: "#132a17", color: "#7be08a" }}><Check size={15} />{t.approveBtn}</button>
            </div>
          )}
          {b.status === "awaiting_arrival" && (
            <div className="flex gap-2 mt-2">
              <button onClick={() => onCancel(b.id)} className="flex-1 rounded-xl py-2.5 font-bold text-sm" style={{ background: "#2a1414", color: "#ff8a8a" }}>{t.barberCancelBtn}</button>
              <button onClick={() => onNoShow(b.id)} className="flex-1 rounded-xl py-2.5 font-bold text-sm" style={{ background: "#2a1414", color: "#ff8a8a" }}>{t.noShowBtn}</button>
              <button onClick={() => onComplete(b.id)} className="flex-1 rounded-xl py-2.5 font-bold text-sm" style={{ background: "#132a17", color: "#7be08a" }}>{t.completeServiceBtn}</button>
            </div>
          )}
        </OwnerBookingCard>
      ))}
    </div>
  );
}

function OwnerBarbers({ bookings, barberPhotos, persistBarberPhotos, showToast }) {
  const { t } = useLang();
  const todayStr = fmtDate(new Date());
  async function handlePhotoChange(barberId, e) {
    const file = e.target.files && e.target.files[0];
    if (!file) return;
    try {
      const dataUrl = await fileToDataUrl(file);
      persistBarberPhotos({ ...barberPhotos, [barberId]: dataUrl });
      showToast(t.photoUpdated);
    } catch { showToast(t.photoUpdateFailed, "err"); }
  }
  return (
    <div className="space-y-3 pb-4">
      {BARBERS.map(b => {
        const completedCount = bookings.filter(x => x.barberId === b.id && x.status === "completed").length;
        const waitingCount = bookings.filter(x => x.barberId === b.id && x.status === "awaiting_arrival").length;
        const todayCount = bookings.filter(x => x.barberId === b.id && x.date === todayStr && x.status === "awaiting_arrival").length;
        const revenue = bookings.filter(x => x.barberId === b.id && x.status === "completed").reduce((s, x) => s + x.totalPrice, 0);
        return (
          <Card key={b.id}>
            <div className="flex items-center gap-3 mb-3">
              <div className="relative inline-block">
                <Avatar photo={getBarberPhoto(b.id, barberPhotos)} initials={b.initials} size={56} />
                <label className="absolute -bottom-1 -left-1 w-6 h-6 rounded-full flex items-center justify-center cursor-pointer" style={{ background: "#C9A227", border: "2px solid #0B0B0C" }}>
                  <Camera size={11} color="#0B0B0C" />
                  <input type="file" accept="image/*" className="hidden" onChange={(e) => handlePhotoChange(b.id, e)} />
                </label>
              </div>
              <div><p className="font-bold text-sm">{b.name}{b.isOwnerManaged && <span className="text-[10px] font-normal mr-1" style={{ color: "#9B9691" }}> ({t.roleOwner})</span>}</p></div>
            </div>
            <div className="grid grid-cols-2 gap-2">
              <MiniStat value={completedCount} label={t.ownerBarbersServed} color="#7be08a" />
              <MiniStat value={waitingCount} label={t.ownerBarbersWaiting} color="#4ba3e8" />
              <MiniStat value={todayCount} label={t.ownerBarbersToday} color="#E8C468" />
              <MiniStat value={`${revenue.toLocaleString()} ${t.currency}`} label={t.ownerBarbersRevenue} color="#E8C468" />
            </div>
          </Card>
        );
      })}
    </div>
  );
}
function MiniStat({ value, label, color }) { return (<div className="rounded-xl text-center py-2.5" style={{ background: "#0B0B0C", border: "1px solid #262220" }}><p className="text-lg font-extrabold" style={{ color }}>{value}</p><p className="text-[10px]" style={{ color: "#9B9691" }}>{label}</p></div>); }
